  const submitRentUpdate = async (event: FormEvent<HTMLFormElement>, rent: NonNullable<typeof editingRent>) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { const receiptUrl = await uploadFromForm(form, "receipt", "receiptUrl", "receipt"); uploadFeedback.markSaving(); await updateRent.mutateAsync({ id: rent.id, buildingId, expectedUpdatedAt: rent.updatedAt, dueDate: String(form.get("dueDate")), expectedAmountPaise: toPaise(String(form.get("expected"))), paidAmountPaise: toPaise(String(form.get("paid"))), paidOn: String(form.get("paidOn")) || undefined, paymentMethod: String(form.get("paymentMethod")) as "cash" | "upi" | "bank_transfer", notes: String(form.get("notes")) || undefined, receiptUrl: receiptUrl || undefined }); } catch (error) { uploadFeedback.clear(); toast.error(error instanceof Error ? error.message : "Receipt could not be uploaded."); } };
